const timezoneQuizQuestions=[{question:"What is India's standard time zone?",options:["UTC+5:00 (IST)","UTC+5:30 (IST)","UTC+6:00 (IST)","UTC+5:15 (IST)"],answer:"UTC+5:30 (IST)",explanation:"India uses a single time zone — Indian Standard Time (IST), which is UTC+5:30, 30 minutes ahead of the nearest whole-hour offset."},{question:"Approximately how wide is India in longitude?",options:["About 10°","About 29°","About 45°","About 60°"],answer:"About 29°",explanation:"India spans from ~68°E (Kutch, Gujarat) in the west to ~97°E (Kibithu, Arunachal Pradesh) in the east — roughly 29° of longitude, or about 3,200 km east-to-west."},{question:"Why does India maintain a single time zone despite its width?",options:["The government hasn't decided yet","National unity and administrative practicality","India is too narrow for multiple zones","All other countries use one zone too"],answer:"National unity and administrative practicality",explanation:"A single time zone was adopted at independence (1947) to preserve national unity. Multiple zones would complicate railways, broadcasting, and administration across a vast country."},{question:"Without IST, the sun would rise roughly how much earlier in eastern India vs western India?",options:["30 minutes","About 2 hours","About 5 hours","No difference"],answer:"About 2 hours",explanation:"Because 29° of longitude translates to ~2 hours of solar time difference (15° ≈ 1 hour). Arunachal Pradesh would see sunrise ~2 hours before Gujarat."},{question:"Which country spans the most time zones due to its overseas territories?",options:["Russia","United States","France","Canada"],answer:"France",explanation:"France spans 12 time zones because of its overseas territories (French Polynesia, New Caledonia, etc.). Russia spans 11 contiguous zones."}];let currentQuestion=0,score=0,answered=!1;function renderQuiz(){const e=document.getElementById("tz-quiz-card");if(!e)return;if(currentQuestion>=timezoneQuizQuestions.length)return void renderResult();answered=!1;const t=timezoneQuizQuestions[currentQuestion],n=currentQuestion/timezoneQuizQuestions.length*100;e.innerHTML=`\n    <div class="tz-quiz-progress">\n      <span class="tz-quiz-progress-text">Q${currentQuestion+1} of ${timezoneQuizQuestions.length}</span>\n      <div class="tz-quiz-progress-bar"><div class="tz-quiz-progress-fill" style="width:${n}%"></div></div>\n    </div>\n    <h3 class="tz-question">${t.question}</h3>\n    <div class="tz-options" id="tz-options"></div>\n    <div class="tz-feedback" id="tz-feedback"></div>\n  `;const s=document.getElementById("tz-options");t.options.forEach(e=>{const n=document.createElement("button");n.className="tz-option-btn",n.textContent=e,n.addEventListener("click",()=>handleAnswer(e,t)),s.appendChild(n)})}function handleAnswer(e,t){if(answered)return;answered=!0;const n=e===t.answer,s=document.querySelectorAll(".tz-option-btn"),o=document.getElementById("tz-feedback");s.forEach(s=>{s.disabled=!0,s.textContent===t.answer&&s.classList.add("correct"),s.textContent!==e||n||s.classList.add("incorrect")}),o.className="tz-feedback show "+(n?"correct-feedback":"incorrect-feedback"),o.innerHTML=`\n    <span class="tz-feedback-icon">${n?"✅":"❌"}</span>\n    <strong>${n?"Correct!":"Not quite."}</strong> — ${t.explanation}\n    <div style="margin-top:0.5rem;font-size:0.8rem;opacity:0.7">Sourced from Survey of India / Government of India Resolution No. 1854 (1947) / timeanddate.com</div>\n  `,n&&score++,setTimeout(()=>{currentQuestion++,renderQuiz()},3500)}function renderResult(){const e=document.getElementById("tz-quiz-card"),t=Math.round(score/timezoneQuizQuestions.length*100);let n="Keep learning! India's time zone story is fascinating.";100===t?n="🏆 Perfect! You're a Time Zone Expert!":t>=60?n="🌟 Great job! You know your Indian geography!":t>=40&&(n="📚 Good effort! Check the explanations above — there's always more to learn."),e.innerHTML=`\n    <div class="tz-result-screen">\n      <div class="tz-result-icon">🕐</div>\n      <h2>Quiz Complete!</h2>\n      <div class="tz-result-score">${score} / ${timezoneQuizQuestions.length} (${t}%)</div>\n      <p class="tz-result-msg">${n}</p>\n      <button class="tz-btn" id="tz-restart-btn">Retry Quiz</button>\n    </div>\n  `,document.getElementById("tz-restart-btn").addEventListener("click",resetQuiz)}function resetQuiz(){currentQuestion=0,score=0,answered=!1,renderQuiz()}document.addEventListener("DOMContentLoaded",renderQuiz);